def algorithm(func, dim, lb, ub, budget, rng):
    def generate_candidate(x_best, x_prev, f_prev, sigma, rng):
        z = rng.normal(size=dim)
        candidate = x_best + sigma * (x_prev - x_best) + 0.5 * sigma * np.dot(z, np.sqrt(np.diag(np.cov((x_prev - x_best).reshape(1, dim), rowvar=False))))
        candidate = np.clip(candidate, lb, ub)
        return candidate

    def generate_initial_population(dim, lb, ub, rng):
        population = lb + (ub - lb) * rng.uniform(size=(budget, dim))
        return population

    sigma = 0.5
    x_best = np.full(dim, (lb + ub) / 2)
    f_best = func(x_best)
    population = generate_initial_population(dim, lb, ub, rng)

    for _ in range(budget):
        x_prev = population[np.argmin([func(c) for c in population])]
        f_prev = func(x_prev)
        for i in range(budget):
            if np.random.rand() < 0.1:
                candidate = generate_candidate(x_best, x_prev, f_prev, sigma, rng)
            else:
                candidate = population[i]
            if func(candidate) < f_best or np.random.rand() < (f_best - func(candidate)) / (f_best - f_prev):
                population[i] = candidate
        x_best = population[np.argmin([func(c) for c in population])]
        f_best = func(x_best)
    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    x = rng.uniform(size=dim) * (ub - lb) + lb
    T = 1.0
    best_x = x.copy()
    best_func_val = func(x)

    for _ in range(budget):
        if np.random.rand() < 0.05:
            # Golden section search to find the better solution
            a, b = x - (ub - lb) / 2.0, x + (ub - lb) / 2.0

            def func_val(a, b):
                return func((1 + np.sqrt(5)) * a + ((b - a) / (1 + np.sqrt(5))))

            c = b
            for _ in range(budget // 10):
                if func_val(c, b) > func_val(a, c):
                    c = (a + c) / 2.0
                else:
                    a = c

            x[a:b] = (1 + np.sqrt(5)) * a + ((b - a) / (1 + np.sqrt(5)))

        # Simulated Annealing
        new_x = rng.uniform(size=dim) * (ub - lb) + lb

        delta = func(new_x) - func(x)
        if delta < 0 or np.random.rand() < np.exp(-delta / T):
            x = new_x

            if func(x) < best_func_val:
                best_x = x.copy()
                best_func_val = func(x)

        # Decrease the temperature
        T *= 0.99

    return best_x

